const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const out = 'docs/performance/focused-review/';
function read(file) {
  const bytes = fs.readFileSync(path.join(root, file));
  return bytes.toString(bytes[0] === 255 && bytes[1] === 254 ? 'utf16le' : 'utf8').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
}
const json = file => JSON.parse(read(file));
const h = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const f = value => Number(value).toFixed(3);
const median = values => [...values].sort((a, b) => a - b)[1];
const link = (file, label = file) => '<a href="' + encodeURI(file) + '">' + h(label) + '</a>';
let sourceId = 0;
function src(file, label, needle = null, count = Infinity, open = false) {
  const lines = read(file).split('\n');
  const first = needle ? lines.findIndex(line => line.includes(needle)) : 0;
  if (first < 0) throw new Error('Missing source anchor: ' + file + ' / ' + needle);
  const last = Math.min(lines.length, first + count);
  const id = 'source-' + (++sourceId);
  const content = lines.slice(first, last).join('\n').trimEnd();
  return '<details class="source"' + (open ? ' open' : '') + '><summary>' + h(label) +
    ' <span class="path" dir="ltr">' + h(file) + ' · L' + (first + 1) + '–' + last + '</span></summary>' +
    '<div class="codebar"><span>كود فعلي من المشروع</span><button class="copy" data-code="' + id + '">نسخ الكود</button></div>' +
    '<pre><code id="' + id + '" dir="ltr" data-source="' + h(file) + '" data-first="' + first + '" data-last="' + last + '">' + h(content) +
    '</code></pre><p class="source-link">' + link(file, 'فتح الملف الأصلي') + '</p></details>';
}
function example(label, code) {
  return '<div class="example"><p>' + h(label) + '</p><pre dir="ltr"><code>' + h(code) + '</code></pre></div>';
}
const database = json(out + 'database.json');
const cache = json(out + 'cache-and-edit-after-gzip.json');
const replica = json(out + 'replica-current.json');
const wireBefore = json(out + 'before-gzip/wire.json');
const wireAfter = json(out + 'after-gzip/wire.json');
const historical = json('docs/checklist/requirement-3/benchmark-summary.json');
const planHistory = json('docs/performance/results/explain-summary.json');
const cleanup = json(out + 'cleanup.json');
const compression = {};
for (const stage of ['before-gzip', 'after-gzip']) {
  const sources = [1, 2, 3].map(run => out + stage + '/k6-' + run + '.json');
  const runs = sources.map(file => json(file).metrics);
  if (runs.some(metrics => metrics.endpoint_errors.value !== 0)) throw new Error('k6 validation errors in ' + stage);
  compression[stage] = {
    p50_ms: median(runs.map(m => m.endpoint_duration['p(50)'])),
    p95_ms: median(runs.map(m => m.endpoint_duration['p(95)'])),
    p99_ms: median(runs.map(m => m.endpoint_duration['p(99)'])),
    requests_per_second: median(runs.map(m => m.http_reqs.rate)),
    received_bytes_per_request: median(runs.map(m => m.data_received.count / m.http_reqs.count)),
    endpoint_error_percent: 0, sources,
  };
}
if (!wireAfter.gzip_active || !wireAfter.passed || !cache.passed) throw new Error('Live verification is incomplete.');
const defaultTests = read(out + 'tests-after-gzip.txt').split('\n').find(line => line.includes('Tests:')).trim();
const mysqlTests = read(out + 'mysql-after-gzip.txt').split('\n').find(line => line.includes('OK (')).trim();
const summary = {
  measured_at: '2026-11-07', dataset: database.counts, compression,
  wire_before: wireBefore, wire_after: wireAfter, replica_current: replica,
  default_tests: defaultTests, mysql_tests: mysqlTests,
  replication_lag_demo: 'Retained real evidence from earlier audit; current review does not pause replication.',
  cleanup, note: 'Three run-level medians; latest paired workload isolates gzip/weak-validator addition on the already optimized backend. Historical pre-index/cache measurements are separate.',
};
fs.writeFileSync(path.join(root, out, 'summary.json'), JSON.stringify(summary, null, 2) + '\n');
const metricRows = Object.entries(compression).map(([stage, m]) => '<tr><th>' + (stage === 'before-gzip' ? 'قبل gzip' : 'بعد gzip') +
  '</th>' + [m.p50_ms, m.p95_ms, m.p99_ms, m.requests_per_second, m.received_bytes_per_request].map(value => '<td class="num">' + f(value) + '</td>').join('') + '<td class="num">0%</td></tr>').join('');
const oldRows = Object.entries(historical.scenarios).map(([scenario, stages]) => {
  const a = stages.archived_before, b = stages.archived_after;
  return '<tr><th dir="ltr">' + h(scenario) + '</th>' + [a.p50, b.p50, a.p95, b.p95, a.p99, b.p99].map(value => '<td class="num">' + f(value) + '</td>').join('') + '</tr>';
}).join('');
const planRows = planHistory.before.map((before, index) => {
  const after = planHistory.after[index];
  return '<tr><td><code>' + h(before.query) + '</code></td><td>' + h(after.key || 'لا يوجد') + '</td><td class="num">' + h(before.root_completion_ms) + '</td><td class="num">' + h(after.root_completion_ms) + '</td></tr>';
}).join('');
const currentPlans = database.queries.map(query => '<tr><td><code>' + h(query.sql) + '</code></td><td><code>' + h(query.explain[0].key || 'NULL') + '</code></td><td class="num">' + query.explain[0].rows + '</td></tr>').join('');
const report = `# Focused backend performance review

All six requested areas were checked in order. Backend gzip was missing and is now implemented and verified directly on port 8000. No frontend source was changed, and no new indexes or migrations were added.

| Area | Result | Evidence |
| --- | --- | --- |
| Slow queries / EXPLAIN ANALYZE / justified indexes / N+1 | Verified; order indexes are used, product scans remain reasonable for 15 rows; no speculative new indexes | database.json; n-plus-one.txt; historical baseline/after plans |
| Primary / replica / routing / lag / read-after-write | Current IO/SQL threads Yes, observed lag 0, routing unit tests pass; retained real paused-replica proof used | replica-current.json; replica-router-tests.txt; earlier docs/checklist replica evidence |
| Redis / cache aside / TTL / invalidation / cacheable data | Live 300-second product and 60-second dashboard TTLs; expiry, editing, category invalidation and deletion pass; stock excluded | cache-and-edit-after-gzip.json |
| ETag / 304 / gzip / response validation | Gzip negotiation, weak shared validator, Vary, compressed Content-Length, decoded JSON and bodyless 304 pass | before-gzip/wire.json; after-gzip/wire.json; HttpCompressionTest |
| k6 / before-after / percentiles / throughput / errors / immediate edits | Three identical runs before and after gzip; HTTP status and decoded schema validated; endpoint errors 0 | before-gzip/k6-*.json; after-gzip/k6-*.json; summary.json; cache-and-edit-after-gzip.json |
| Documentation / discovered problems / differences | Detailed Arabic RTL guide with actual embedded code, source lines, archived/current measurements and cleanup manifest | ../../../PERFORMANCE_GUIDE_AR.html; cleanup.json |

Final regression results: ${defaultTests}; ${mysqlTests}.

The new paired test compares the already optimized application before/after adding gzip and a weak ETag suitable for identity/gzip variants. Dataset: ${JSON.stringify(database.counts)}. Five VUs, 5/20/5-second stages, one-second think time, public full product page, no If-None-Match requests. Latency is milliseconds; each number is the median of three run-level metrics, not the percentile of pooled samples.

| Stage | p50 ms | p95 ms | p99 ms | req/s | received bytes/request including headers | endpoint errors |
| --- | ---: | ---: | ---: | ---: | ---: | ---: |
${Object.entries(compression).map(([stage, m]) => '| ' + stage + ' | ' + [m.p50_ms, m.p95_ms, m.p99_ms, m.requests_per_second, m.received_bytes_per_request].map(f).join(' | ') + ' | 0% |').join('\n')}

Direct wire body changed from ${wireBefore.identity_body_bytes} to ${wireAfter.gzip_requested_body_bytes} bytes (${wireAfter.saved_body_percent.toFixed(2)}% smaller). Decompression produces the exact same ${wireAfter.decoded_body_bytes}-byte JSON. This is transfer reduction, not a claim of increased maximum capacity or uniformly faster latency. Preserve all raw runs, including regressions and earlier dashboard tail variation.

Current replica status is a point-in-time observation. The replication-pause replay was not authorized in this turn, so it was not run again; the earlier real GTID/paused-replica proof is retained and clearly labeled. The current router was re-tested without modifying replication. Product edit visibility means the next API read is current; no automatic browser DOM refresh is claimed.

Cleanup follows the conservative scope because no broader cleanup preference was provided: remove only proven generated Python bytecode after verifying resolved paths are inside this workspace; keep code, dependencies, local environments, secrets, historical reports, raw benchmarks and source snapshots. No database volume or application data was deleted. Exact paths are in cleanup.json.

## Reproduce

Use the existing isolated test container with explicit SQLite settings for the default suite and phpunit.mysql.xml for guarded MySQL tests. Copy perf/verify-compression.php into the backend container and run it with --expect-gzip. The paired k6 script is perf/k6/compression.js; use the same dataset, VUs and duration and separate output directories. Saved image IDs identify both measured runtimes. Earlier pre-index/cache evidence remains under docs/performance/baseline and results; do not reset the current 300,004-order dataset to replay it.

The HTML is generated by node perf/build-performance-guide.cjs and validated by node perf/verify-performance-guide.cjs. Source snippets are embedded from current files and checked byte-for-byte after normalizing line endings. The guide is standalone and needs no external assets.
`;
fs.writeFileSync(path.join(root, out, 'REVIEW.md'), report);
